import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Identify strong candidates based on mean difference and t-test
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if abs(mean_diff) > 0.2 and abs(t_stat) > 3:
            candidates.append((fid, mean_diff, t_stat))

    # Sort by absolute t-statistic
    candidates.sort(key=lambda x: abs(x[2]), reverse=True)

    # Check for correlated pairs
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Look for product terms
    drivers = []
    columns = []
    products = []
    loadings = {}

    # Try to find a pair that works well together
    for (fid1, fid2), corr in correlations.items():
        if len(drivers) >= MAX_DRIVERS:
            break

        # Check if both features are strong candidates
        if any(c[0] == fid1 for c in candidates[:10]) and any(c[0] == fid2 for c in candidates[:10]):
            # Add both features to columns
            columns.extend([fid1, fid2])

            # Add their product
            products.append((fid1, fid2))

            # Add to drivers (most significant first)
            if not any(d == fid1 for d in drivers):
                drivers.append(fid1)
            if not any(d == fid2 for d in drivers):
                drivers.append(fid2)

            # Weighted loading (based on correlation strength)
            loadings[fid1] = abs(corr)
            loadings[fid2] = abs(corr)

    # If no good product found, try single features
    if not products and candidates:
        # Use top candidates as drivers and columns
        for fid, _, _ in candidates[:MAX_DRIVERS]:
            if fid not in drivers:
                drivers.append(fid)
            if fid not in columns:
                columns.append(fid)
            loadings[fid] = 1.0

    # Ensure we don't exceed MAX_DRIVERS
    if len(drivers) > MAX_DRIVERS:
        drivers = drivers[:MAX_DRIVERS]

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

